parameters.jsCode:
// ============================================
// CHUNK CV DATA (ENRICHED + RAW SPLIT)
// ============================================

// Get extracted data from Information Extractor
const extracted = $('Information Extractor').first().json.output;

// Get raw CV text from CV node (adjust field name if needed)
const rawCV = $('CV').first().json.cv || $('CV').first().json.markdown || '';

// Helper to format lists and objects
function formatList(items, separator = '\n') {
  if (!items || items.length === 0) return 'Not specified';
  if (Array.isArray(items)) {
    return items.map(item => {
      if (typeof item === 'string') return `• ${item}`;
      if (typeof item === 'object') {
        return Object.entries(item).map(([k, v]) => {
          if (Array.isArray(v)) return `  - ${k}: ${v.join(', ')}`;
          return `  - ${k}: ${v}`;
        }).join('\n');
      }
      return String(item);
    }).join(separator);
  }
  return String(items);
}

// Helper to split raw CV into overlapping chunks
function splitText(text, chunkSize = 1000, overlap = 100) {
  if (!text || text.length <= chunkSize) return [text];
  const chunks = [];
  let start = 0;
  while (start < text.length) {
    const end = Math.min(start + chunkSize, text.length);
    chunks.push(text.substring(start, end));
    if (end === text.length) break;
    start = end - overlap;
    if (start < 0) start = 0;
    // Avoid infinite loop if chunkSize <= overlap
    if (start === 0 && end === text.length) break;
  }
  return chunks;
}

// ---------- STRUCTURED CHUNKS (enriched) ----------

// 1. Profile & Value Proposition
const profileChunk = {
  chunk_type: 'profile_value_proposition',
  content: `👤 PROFILE & VALUE PROPOSITION

Professional Identity:
${extracted.professional_identity || 'Not specified'}

Professional Summary:
${extracted.professional_summary || 'Not specified'}

Value Proposition:
${extracted.value_proposition || 'Not specified'}

Core Competencies:
${formatList(extracted.core_competencies)}

Soft Skills:
${formatList(extracted.soft_skills)}`,
  metadata: {
    section: 'profile',
    fields: ['professional_identity', 'professional_summary', 'value_proposition', 'core_competencies', 'soft_skills'],
    context_type: 'personal_profile',
    retrieval_priority: 'high'
  }
};

// 2. Research & Academic Background
const researchChunk = {
  chunk_type: 'research_academic',
  content: (() => {
    const parts = [];
    if (extracted.research_background) {
      parts.push(`🔬 RESEARCH BACKGROUND
Field: ${extracted.research_background.field || 'N/A'}
Thesis: ${extracted.research_background.thesis_title || 'N/A'}
Institution: ${extracted.research_background.institution || 'N/A'}
Key Contribution: ${extracted.research_background.key_contribution || 'N/A'}
Transferable Skills: ${formatList(extracted.research_background.transferable_skills, ', ')}`);
    }
    if (extracted.education && extracted.education.length > 0) {
      parts.push(`🎓 EDUCATION
${extracted.education.map(edu => `${edu.degree} - ${edu.institution} (${edu.year || '?'})${edu.research_focus ? `\n  Research Focus: ${edu.research_focus}` : ''}`).join('\n')}`);
    }
    if (extracted.international_experience && extracted.international_experience.length > 0) {
      parts.push(`🌍 INTERNATIONAL EXPERIENCE
${extracted.international_experience.map(exp => `${exp.country} - ${exp.institution}${exp.skills_gained ? `\n  Skills Gained: ${exp.skills_gained.join(', ')}` : ''}`).join('\n')}`);
    }
    return parts.join('\n\n') || 'No research background available.';
  })(),
  metadata: {
    section: 'academic_background',
    fields: ['research_background', 'education', 'international_experience'],
    context_type: 'research',
    retrieval_priority: 'high',
    topics: ['PhD', 'Thermal Field Theory', 'Quark-Gluon Plasma', 'Polyakov loops', 'Gradient Flow']
  }
};

// 3. AI Engineering & Technical Skills
const aiSkillsChunk = {
  chunk_type: 'ai_technical_skills',
  content: (() => {
    const parts = [];
    if (extracted.ai_engineering_skills && extracted.ai_engineering_skills.length > 0) {
      parts.push(`🤖 AI ENGINEERING SKILLS
${extracted.ai_engineering_skills.map(skill => `${skill.skill_area} (${skill.proficiency_level || 'N/A'})
  Tools: ${skill.tools ? skill.tools.join(', ') : 'N/A'}`).join('\n\n')}`);
    }
    if (extracted.technical_skills) {
      parts.push(`💻 TECHNICAL SKILLS (categorized)
${formatList(extracted.technical_skills)}`);
    }
    if (extracted.ai_training_experience) {
      parts.push(`📚 AI TRAINING EXPERIENCE
Focus Areas: ${formatList(extracted.ai_training_experience.focus_areas, ', ')}
Methodologies: ${formatList(extracted.ai_training_experience.methodologies, ', ')}
Skills Demonstrated: ${formatList(extracted.ai_training_experience.skills_demonstrated, ', ')}`);
    }
    return parts.join('\n\n') || 'No AI skills available.';
  })(),
  metadata: {
    section: 'technical',
    fields: ['ai_engineering_skills', 'technical_skills', 'ai_training_experience'],
    context_type: 'skills',
    retrieval_priority: 'high',
    keywords: ['Pydantic AI', 'LangGraph', 'n8n', 'RAG', 'Agentic AI', 'LLM training']
  }
};

// 4. Business Domains & Microenterprise Expertise
const businessChunk = {
  chunk_type: 'business_microenterprise',
  content: (() => {
    const parts = [];
    if (extracted.business_domains && extracted.business_domains.length > 0) {
      parts.push(`🏢 BUSINESS DOMAINS
${extracted.business_domains.map(domain => `${domain.domain}
  Applications: ${formatList(domain.applications, ', ')}
  Technologies: ${domain.technologies_used ? domain.technologies_used.join(', ') : 'N/A'}`).join('\n\n')}`);
    }
    if (extracted.microenterprise_expertise) {
      parts.push(`🏪 MICROENTERPRISE EXPERTISE
Pain Points Addressed: ${formatList(extracted.microenterprise_expertise.pain_points_addressed, ', ')}
Solutions Deployed: ${formatList(extracted.microenterprise_expertise.solutions_deployed, ', ')}
Industries Served: ${formatList(extracted.microenterprise_expertise.industries_served, ', ')}`);
    }
    if (extracted.professional_experience && extracted.professional_experience.length > 0) {
      parts.push(`💼 PROFESSIONAL EXPERIENCE
${extracted.professional_experience.map(exp => `${exp.role} at ${exp.company} (${exp.period || '?'})
  Key Achievements: ${formatList(exp.key_achievements, '; ')}`).join('\n\n')}`);
    }
    return parts.join('\n\n') || 'No business domain information available.';
  })(),
  metadata: {
    section: 'business',
    fields: ['business_domains', 'microenterprise_expertise', 'professional_experience'],
    context_type: 'business',
    retrieval_priority: 'high',
    keywords: ['microenterprise', 'automation', 'accounting', 'clinical records', 'legal', 'customer support']
  }
};

// 5. Keywords & Search Terms
const keywordsChunk = {
  chunk_type: 'keywords_search_terms',
  content: `🔑 KEYWORDS & SEARCH TERMS
${formatList(extracted.keywords_for_search, ', ')}`,
  metadata: {
    section: 'keywords',
    fields: ['keywords_for_search'],
    context_type: 'search',
    retrieval_priority: 'medium'
  }
};

// ---------- RAW CV CHUNKS (multiple) ----------

const rawChunks = splitText(rawCV, 1200, 150); // 1200 chars per chunk, 150 overlap

const rawChunkObjects = rawChunks.map((chunkText, idx) => ({
  chunk_type: `raw_cv_part_${idx + 1}`,
  content: chunkText,
  metadata: {
    section: 'raw_cv',
    fields: ['raw_text'],
    context_type: 'original',
    retrieval_priority: 'low',
    part_number: idx + 1,
    total_raw_parts: rawChunks.length
  }
}));

// Combine all chunks
const allChunks = [
  profileChunk,
  researchChunk,
  aiSkillsChunk,
  businessChunk,
  keywordsChunk,
  ...rawChunkObjects
];

// Set sequential chunk_index and total_chunks
allChunks.forEach((chunk, idx) => {
  chunk.chunk_index = idx;
  chunk.total_chunks = allChunks.length;
  chunk.source_file = 'CV.pdf'; // adjust as needed
});

console.log(`✅ Created ${allChunks.length} enriched + raw chunks for CV`);

return allChunks.map(chunk => ({
  json: {
    chunk_index: chunk.chunk_index,
    total_chunks: chunk.total_chunks,
    chunk_type: chunk.chunk_type,
    chunk_content: chunk.content,
    chunk_metadata: chunk.metadata,
    source_file: chunk.source_file
  }
}));

// Format CV chunks for Mistral Embedding API
const chunkData = $input.all();

const formattedRequests = chunkData.map(item => {
  return {
    json: {
      formatted_request: {
        input: item.json.chunk_content,
        model: "mistral-embed"
      },
      chunk_identifier: {
        chunk_index: item.json.chunk_index,
        chunk_type: item.json.chunk_type
      },
      original_data: item.json
    }
  };
});

console.log(`📤 Formatted ${formattedRequests.length} chunks for embedding`);
return formattedRequests;

// ============================================
// PREPARE CV DATA FOR SUPABASE
// Combine embeddings with chunk data and full extracted CV
// ============================================

const httpResponses = $input.all();
console.log(`🔍 Processing ${httpResponses.length} embedding responses for CV chunks`);

// Filter successful embedding responses
const successfulResponses = httpResponses.filter(response => {
    const isError = response.error || 
                    (response.json && response.json.error) ||
                    (response.statusCode && response.statusCode >= 400);
    if (isError) {
        console.warn(`⚠️ Skipping error response:`, response.error || response.json?.error);
        return false;
    }
    const hasEmbedding = response?.json?.data?.[0]?.embedding;
    if (!hasEmbedding) {
        console.warn(`⚠️ Skipping response without embedding`);
        return false;
    }
    return true;
});

console.log(`✅ Filtered to ${successfulResponses.length} successful responses`);

// Get original chunk data from the formatting node
const formatNode = $('Format CV Chunks for Embedding');
if (!formatNode || !formatNode.all) {
    throw new Error('❌ Cannot access Format CV Chunks for Embedding node');
}
const formatItems = formatNode.all();
console.log(`🔍 Found ${formatItems.length} chunks from Format CV Chunks for Embedding`);

// Get full extracted CV data
const cvData = $('Information Extractor').first().json.output;

// Process each successful embedding response
const results = successfulResponses.map((httpResponse, index) => {
    const embedding = httpResponse.json.data[0].embedding;
    if (embedding.length !== 1024) {
        console.warn(`⚠️ Unexpected embedding dimension: ${embedding.length} (expected 1024)`);
    }

    // Match chunk data by index
    const chunkData = formatItems[index]?.json?.original_data;
    if (!chunkData) {
        throw new Error(`❌ Could not find chunk data for index ${index}`);
    }

    console.log(`✅ Processing chunk ${chunkData.chunk_index + 1}/${chunkData.total_chunks} (${chunkData.chunk_type})`);

    // Build metadata: combine core chunk info + full extracted CV data (for rich retrieval)
    const metadata = {
        source: 'cv',
        document_type: 'personal_cv',
        extracted_at: new Date().toISOString(),
        full_name: cvData.full_name,
        current_title: cvData.current_title,
        chunk_info: {
            chunk_index: chunkData.chunk_index,
            total_chunks: chunkData.total_chunks,
            chunk_type: chunkData.chunk_type,
            section: chunkData.chunk_metadata.section,
            fields: chunkData.chunk_metadata.fields,
            retrieval_priority: chunkData.chunk_metadata.retrieval_priority || 'medium',
            context_type: chunkData.chunk_metadata.context_type || 'general'
        },
        cv_data: {
            // Include all relevant extracted fields (you can restrict to what's needed)
            education: cvData.education,
            research_experience: cvData.research_experience,
            publications: cvData.publications,
            technical_skills: cvData.technical_skills,
            soft_skills: cvData.soft_skills,
            professional_experience: cvData.professional_experience,
            international_mobility: cvData.international_mobility,
            languages: cvData.languages,
            awards_and_grants: cvData.awards_and_grants,
            certifications: cvData.certifications,
            projects: cvData.projects,
            key_strengths: cvData.key_strengths
        },
        retrieval_optimized: true
    };

    return {
        json: {
            content: chunkData.chunk_content,
            embedding: embedding,
            metadata: metadata,
            chunk_index: chunkData.chunk_index,
            total_chunks: chunkData.total_chunks,
            source_file: chunkData.source_file || 'CV.pdf'
        }
    };
});

console.log(`✅ Successfully processed ${results.length} CV chunks`);
return results;
